@@ -1,6 +1,33 @@
 export type Query = Record<string, string | string[]>;
+
+/** Decode one key or value: `+` becomes a space, then percent-escapes are
+ * resolved when the whole part is valid; otherwise it is kept as written. */
+function decode(part: string): string {
+  const withSpaces = part.replaceAll("+", " ");
+  try {
+    return decodeURIComponent(withSpaces);
+  } catch {
+    return withSpaces;
+  }
+}

 /** Parse a URL query string. See README.md for the rules. */
 export function parseQuery(query: string): Query {
-  throw new Error("not implemented");
+  const pairs = new Map<string, string | string[]>();
+  let body = query.startsWith("?") ? query.slice(1) : query;
+  for (const raw of body.split("&")) {
+    if (raw === "") continue;
+    const eq = raw.indexOf("=");
+    const key = decode(eq === -1 ? raw : raw.slice(0, eq));
+    const value = decode(eq === -1 ? "" : raw.slice(eq + 1));
+    const existing = pairs.get(key);
+    if (existing === undefined) {
+      pairs.set(key, value);
+    } else if (Array.isArray(existing)) {
+      existing.push(value);
+    } else {
+      pairs.set(key, [existing, value]);
+    }
+  }
+  return Object.fromEntries(pairs);
 }
